class Solution:
    def checkValidString(self, s: str) -> bool:
        def dfs(i: int, opened: int) -> bool:
            if opened < 0:
                return False
            if i == len(s):
                return opened == 0
            if s[i] == "(":
                return dfs(i + 1, opened + 1)
            if s[i] == ")":
                return dfs(i + 1, opened - 1)
            return (
                dfs(i + 1, opened + 1) or
                dfs(i + 1, opened - 1) or
                dfs(i + 1, opened)
            )

        return dfs(0, 0)

