from functools import lru_cache

class Solution:
    def checkValidString(self, s: str) -> bool:
        @lru_cache(None)
        def possible(i: int, opened: int) -> bool:
            if opened < 0:
                return False
            if i == len(s):
                return opened == 0
            if s[i] == "(":
                return possible(i + 1, opened + 1)
            if s[i] == ")":
                return possible(i + 1, opened - 1)
            return any((
                possible(i + 1, opened + 1),
                possible(i + 1, opened - 1),
                possible(i + 1, opened),
            ))

        return possible(0, 0)

